	<div class='quest' data-qid='7643' style='margin-left:0px; width: calc(100% - 45px);' data-rewards='REWARD_GIFT REWARD_GIVE_RANDOM_SCROLL_LVL ' data-servers='Miner Military Econom Tactical ' data-timeout='0' data-pearls='0'>
